
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wb97x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wb97x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.559213695229961e+00, -3.489240804086191e+00, -3.391301284957165e+00, -3.255874342538432e+00, -3.071883791719503e+00, -2.828215471092115e+00, -2.517129738816482e+00, -2.139779760716262e+00, -1.711121001562830e+00, -1.259447516730038e+00, -8.293666426293346e-01, -4.998044746485808e-01, -4.171783735554661e-01, -3.191569065650040e-01, -1.976370980997796e-01, -7.683077689445347e-02, -1.527712742697300e-02, 1.428857460396987e-03, -1.407778543133932e-04, -1.192413581806174e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


